import "core-js/modules/es.array.push.js";
/* eslint-disable */
import SnackBar from "@/components/SnackBar.vue";
import MyChannels from "@/components/Channels/MyChannels.vue";
import OtherChannelList from "@/components/Channels/OtherChannelList.vue";
import CreateChannel from "@/components/Channels/AllDialogs/CreateChannel.vue";
export default {
  components: {
    SnackBar,
    MyChannels,
    OtherChannelList,
    CreateChannel
  },
  data() {
    return {
      channelsToggle: "subscribed",
      SnackBarComponent: {},
      createChannelDialog: false,
      componentCheck: 0,
      countCheck: 0,
      isVisible: false
    };
  },
  methods: {
    back_call() {
      this.$router.push("/DashboardView");
    },
    create_channel() {
      this.isVisible = true;
      this.createChannelDialog = true;
      this.componentCheck = 1;
    },
    success_msg(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.createChannelDialog = false;
      this.countCheck += 1;
    },
    error_msg(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    }
  }
};
